/**
 * FFI 统一错误类型。
 */
sealed class CoreFfiException: kotlin.Exception() {
    
    class InvalidAddress(
        
        val `msg`: kotlin.String
        ) : CoreFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidEndpoint(
        
        val `msg`: kotlin.String
        ) : CoreFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InvalidJson(
        
        val `msg`: kotlin.String
        ) : CoreFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreFfiException = FfiConverterTypeCoreFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreFfiError : FfiConverterRustBuffer<CoreFfiException> {
    override fun read(buf: ByteBuffer): CoreFfiException {
        

        return when(buf.getInt()) {
            1 -> CoreFfiException.InvalidAddress(
                FfiConverterString.read(buf),
                )
            2 -> CoreFfiException.InvalidEndpoint(
                FfiConverterString.read(buf),
                )
            3 -> CoreFfiException.InvalidJson(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreFfiException): ULong {
        return when(value) {
            is CoreFfiException.InvalidAddress -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreFfiException.InvalidEndpoint -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreFfiException.InvalidJson -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: CoreFfiException, buf: ByteBuffer) {
        when(value) {
            is CoreFfiException.InvalidAddress -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreFfiException.InvalidEndpoint -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreFfiException.InvalidJson -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalLong: FfiConverterRustBuffer<kotlin.Long?> {
    override fun read(buf: ByteBuffer): kotlin.Long? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterLong.read(buf)
    }

    override fun allocationSize(value: kotlin.Long?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterLong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Long?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterLong.write(value, buf)
        }
    }
}




